        AWS_REGION = 'us-east-1'
        AWS_ROLE_ARN = credentials('ciroos-aws-role-arn')
    }

    stages {
        stage('Discover AWS Services') {
            steps {
                script {
                    def response = sh(
                        script: """
                            curl -s -X GET '${API_BASE_URL}/cloud-providers/aws/services' \\
                            -H 'x-organization-id: ${ORGANIZATION_ID}' \\
                            -H 'x-user-id: ${USER_ID}'
                        """,
                        returnStdout: true
                    ).trim()

                    def data = readJSON text: response
                    echo "Discovered ${data.data.services.size()} AWS services"
                }
            }
        }

        stage('Register AWS Account') {
            steps {
                script {
                    def accountRequest = [
                        account_name: env.AWS_ACCOUNT_NAME,
                        account_id: env.AWS_ACCOUNT_ID,
                        role_arn: env.AWS_ROLE_ARN,
                        region: env.AWS_REGION,
                        tags: [
                            environment: 'production',
                            managed_by: 'jenkins'
                        ]
                    ]

                    def response = sh(
                        script: """
                            curl -s -X POST '${API_BASE_URL}/cloud-accounts/aws' \\
                            -H 'x-organization-id: ${ORGANIZATION_ID}' \\
                            -H 'x-user-id: ${USER_ID}' \\
                            -H 'Content-Type: application/json' \\
                            -d '${groovy.json.JsonOutput.toJson(accountRequest)}'
                        """,
                        returnStdout: true
                    ).trim()

                    def data = readJSON text: response
                    env.CLOUD_ACCOUNT_ID = data.data.id
                    echo "Registered cloud account: ${env.CLOUD_ACCOUNT_ID}"
                }
            }
        }

        stage('Verify Cloud Account') {
            steps {
                script {
                    def response = sh(
                        script: """
                            curl -s -X POST \\
                            '${API_BASE_URL}/cloud-accounts/${env.CLOUD_ACCOUNT_ID}/verify' \\
                            -H 'x-organization-id: ${ORGANIZATION_ID}' \\
                            -H 'x-user-id: ${USER_ID}'
                        """,
                        returnStdout: true
                    ).trim()

                    def data = readJSON text: response
                    if (data.data.status != 'success') {
                        error "Cloud account verification failed"
                    }
                    echo "✓ Cloud account verified successfully"
                }
            }
        }

        stage('Discover EKS Clusters') {
            steps {
                script {
                    def response = sh(
                        script: """
                            curl -s -X GET \\
                            '${API_BASE_URL}/cloud-providers/aws/eks?account_id=${env.CLOUD_ACCOUNT_ID}' \\
                            -H 'x-organization-id: ${ORGANIZATION_ID}' \\
                            -H 'x-user-id: ${USER_ID}'
                        """,
                        returnStdout: true
                    ).trim()

                    def data = readJSON text: response
                    def totalClusters = 0
                    data.data.regions.each { region ->
                        totalClusters += region.clusters.size()
                    }
                    echo "Discovered ${totalClusters} EKS clusters"
                }
            }
        }
    }

    post {
        success {
            echo "✓ Cloud onboarding pipeline completed successfully"
        }
        failure {
            echo "✗ Cloud onboarding pipeline failed"
        }
    }
}
